import{I as e,P as t,Q as n,n as r}from"./chunks/framework.BmaFRZVf.js";var i=JSON.parse(`{"title":"Drop Harness Hooks and Sync Beads Across Machines","description":"","frontmatter":{"id":"proposal.0007","title":"Drop Harness Hooks and Sync Beads Across Machines","authors":["markmals","anthropic/claude-opus-5-5"],"status":"draft","pull-request":"https://github.com/markmals/workbench/pull/11","issues":[],"supersedes":[]},"headers":[],"relativePath":"proposals/0007-drop-harness-hooks-and-sync-beads.md","filePath":"proposals/0007-drop-harness-hooks-and-sync-beads.md"}`),a={name:`proposals/0007-drop-harness-hooks-and-sync-beads.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="drop-harness-hooks-and-sync-beads-across-machines" tabindex="-1">Drop Harness Hooks and Sync Beads Across Machines <a class="header-anchor" href="#drop-harness-hooks-and-sync-beads-across-machines" aria-label="Permalink to “Drop Harness Hooks and Sync Beads Across Machines”">​</a></h1><h2 id="summary" tabindex="-1">Summary <a class="header-anchor" href="#summary" aria-label="Permalink to “Summary”">​</a></h2><p>Remove the OMP extensions that run on every turn, deliver Beads ready work and memories through <code>mise run status</code>, and sync each project&#39;s Beads database across machines through its own GitHub repository without publishing a Git branch.</p><h2 id="motivation" tabindex="-1">Motivation <a class="header-anchor" href="#motivation" aria-label="Permalink to “Motivation”">​</a></h2><p>This proposal fixes two problems in how agent sessions run.</p><p><strong>The harness hooks slow the agent loop.</strong> Workbench wires three OMP extensions into every session:</p><ul><li><code>check-before-stop</code> runs the full <code>mise run check</code> at the end of every turn, including turns that changed nothing. That costs 4.7 s per turn in Workbench. In Trove, whose check takes 4–8 minutes, the hook always times out and sends the agent back once (<a href="./0003-fit-the-harness-to-current-models">proposal 0003</a>). Recon replaced the hook with a no-op because it kept blocking stops.</li><li><code>format-after-edit</code> runs the formatter after every edit. That costs 0.26 s per edit, plus a model round trip to re-read the file whenever it reformats.</li><li><code>prime-beads</code> injects <code>bd prime</code> before the first turn: 8,444 characters, sent with every request. Before 2026-11-15 Workbench had no Beads memories, so all of it was generic Beads guidance. That guidance includes <code>git add . &amp;&amp; git commit</code>, which contradicts the project&#39;s commit rules.</li></ul><p>The owner&#39;s top performance priority is the speed of the agent loop. Everything these hooks enforce is also enforced, or can be, at points outside it.</p><p><strong>Agents on different machines do not share their work graph.</strong> The owner now runs agents on the same project from several machines. Each machine keeps its own Beads (Dolt) database.</p><p>Every Workbench project in <code>~/Developer</code> already points <code>sync.remote</code> at its own GitHub repository, and most have published Beads history there. But nothing in the process says when to pull or push. A machine therefore sees another&#39;s claims and new items only after someone remembers to run <code>bd dolt pull</code>.</p><p>Recon took a different route and turned on <code>dolt.auto-push</code>. Beads documents that setting as safe only for a single writer. Recon&#39;s repository also now carries a <code>__dolt_remote_info__</code> branch. Dolt publishes that branch so the remote appears in GitHub&#39;s interface, and GitHub then shows its banner announcing a recently pushed branch.</p><p>The owner wants every machine to have current Beads, including what other agents have claimed, without that noise.</p><h2 id="domain-grounding" tabindex="-1">Domain grounding <a class="header-anchor" href="#domain-grounding" aria-label="Permalink to “Domain grounding”">​</a></h2><h3 id="established-context" tabindex="-1">Established context <a class="header-anchor" href="#established-context" aria-label="Permalink to “Established context”">​</a></h3><p>Beads (bd 1.3.2, documentation in <code>gastownhall/beads</code>):</p><ul><li><p><strong>The Dolt database is the source of truth.</strong> <code>.beads/issues.jsonl</code> is an export for viewers and backup, not a cross-machine sync channel. Importing JSONL is upsert-only and cannot see deletions (<code>docs/core-concepts/sync-concepts.md</code>).</p></li><li><p><strong>Sync runs over Dolt remotes.</strong> A project&#39;s own <code>origin</code> can serve as its Dolt remote. Dolt stores the history under <code>refs/dolt/data</code>, separate from source branches. <code>bd bootstrap</code> clones that history onto a fresh machine and never deletes existing data (<code>docs/getting-started/sync-setup.md</code>, <code>bd bootstrap --help</code>).</p></li><li><p><strong><code>bd sync</code> runs one full cycle</strong> (<code>bd sync --help</code>):</p><ol><li>Pull from the remote.</li><li>Detect conflicts from the merge itself rather than from the pull&#39;s exit status.</li><li>Recompute blocked flags.</li><li>Push, retrying a bounded number of times when another replica wins the push race.</li></ol><p>The pull settles some conflicts on its own, including last-write-wins on individual issue fields. A conflict it cannot resolve safely halts the cycle with exit status 2. A working set left dirty by another writer exits 4.</p></li><li><p><strong><code>dolt.auto-push</code> is opt-in.</strong> It pushes after writes, debounced to one push per interval. Beads warns that &quot;concurrent pushes to git-protocol Dolt remotes can corrupt or strand remote history when multiple writers race&quot; (<code>docs/reference/configuration.md</code>).</p></li><li><p><strong>Other remote types exist.</strong> Beads supports DoltHub, S3, GCS, Git, and file remotes. It names DoltHub the zero-configuration default for syncing across machines and documents bucket-based syncing as an alternative (<code>docs/architecture/dolt.md</code>, <code>docs/multi-agent/bucket-federation.md</code>).</p></li></ul><p>Dolt:</p><ul><li><strong>Data location.</strong> A Git-hosted Dolt remote keeps its data in <code>refs/dolt/data</code>, outside <code>refs/heads/</code>, so it never collides with branches (<a href="https://docs.dolthub.com/sql-reference/version-control/remotes" target="_blank" rel="noreferrer">remotes</a>, <a href="https://www.dolthub.com/blog/2026-02-19-supporting-git-remotes-as-dolt-remotes/" target="_blank" rel="noreferrer">Git remotes</a>).</li><li><strong>The info branch.</strong> <code>refs/heads/__dolt_remote_info__</code> is an ordinary branch holding one <code>DOLT_REMOTE.md</code> file. It exists so the remote appears in GitHub&#39;s interface, and nothing reads it back. An empty <code>DOLT_REMOTE_INFO_BRANCH</code> environment variable disables it (<a href="https://github.com/dolthub/dolt/issues/11648" target="_blank" rel="noreferrer">dolt#11648</a>, <a href="https://github.com/gastownhall/beads/issues/5266" target="_blank" rel="noreferrer">beads#5266</a>, <a href="https://github.com/gastownhall/beads/pull/8106" target="_blank" rel="noreferrer">beads#8106</a>). <a href="https://github.com/gastownhall/beads/pull/7945" target="_blank" rel="noreferrer">beads#7945</a>, which would stop bd publishing the branch by default, is still open.</li><li><strong>A mirror push destroys the data.</strong> <code>git push --mirror</code> from an ordinary clone deletes <code>refs/dolt/data</code> on the remote, because ordinary clones never fetch it (<a href="https://github.com/gastownhall/beads/issues/5266" target="_blank" rel="noreferrer">beads#5266</a>).</li></ul><h3 id="repository-observations" tabindex="-1">Repository observations <a class="header-anchor" href="#repository-observations" aria-label="Permalink to “Repository observations”">​</a></h3><p>Checked on 2026-11-15:</p><ul><li><strong>Remote inventory.</strong><ul><li>Workbench, Pico, Trove, and Recon set <code>sync.remote</code> to their own GitHub repository, and each has <code>refs/dolt/data</code>.</li><li>Bento sets <code>sync.remote</code>, but its repository has no <code>refs/dolt/data</code> yet.</li><li>Recon also sets <code>dolt.auto-push: true</code>. Its repository has <code>refs/heads/__dolt_remote_info__</code>, with one commit, &quot;dolt remote info&quot;, from 2026-11-14.</li></ul></li><li><strong>The info branch, reproduced against local bare repositories:</strong><ul><li>The Dolt 2.7.3 CLI&#39;s push created <code>refs/heads/__dolt_remote_info__</code>.</li><li>The same push with <code>DOLT_REMOTE_INFO_BRANCH=</code> created only <code>refs/dolt/data</code>.</li><li>A later push left the existing info branch unchanged.</li><li>bd 1.3.2&#39;s own push to a <code>git+file</code> remote created no info branch.</li></ul></li><li><strong>Two replicas, simulated with two clones of one bare repository:</strong><ul><li>Clone B ran <code>bd bootstrap</code>, claimed an item, and ran <code>bd sync</code>.</li><li>Clone A created an item and ran <code>bd sync</code>. A then showed B&#39;s claim, in progress with its assignee.</li><li>B&#39;s next <code>bd sync</code> received A&#39;s item.</li><li>The remote held only <code>main</code> and <code>refs/dolt/data</code>.</li></ul></li><li><strong>Latency.</strong> <code>bd dolt pull</code> against Workbench&#39;s real GitHub remote took 1.28 s.</li><li><strong>mise environment.</strong> mise exports an <code>[env]</code> value of <code>&quot;&quot;</code> as a set, empty variable, both to <code>mise exec</code> and to tasks.</li><li><strong>Measured hook costs.</strong><ul><li><code>mise run check</code> takes 4.7 s in Workbench, and the 4–8 minutes in Trove come from <a href="./0003-fit-the-harness-to-current-models">proposal 0003</a>.</li><li><code>bd prime</code> took 0.7 s and printed 8,444 characters. With <code>--memories-only</code> it printed 2,831, all of them memories recorded that day.</li><li><code>mise run fmt</code> on one file took 0.26 s.</li></ul></li></ul><h3 id="relevant-constraints-and-principles" tabindex="-1">Relevant constraints and principles <a class="header-anchor" href="#relevant-constraints-and-principles" aria-label="Permalink to “Relevant constraints and principles”">​</a></h3><table tabindex="0"><thead><tr><th>Concept</th><th>Identity and lifetime</th></tr></thead><tbody><tr><td>Beads replica</td><td>One machine&#39;s local Dolt database for a project: a full copy that works offline. Lives in that checkout&#39;s <code>.beads/</code>.</td></tr><tr><td>Beads remote</td><td><code>refs/dolt/data</code> on the project&#39;s own GitHub repository. The meeting point of the replicas; never a branch.</td></tr><tr><td>Sync</td><td>One <code>bd sync</code> cycle: pull, conflict check, push with retries.</td></tr><tr><td>Sync point</td><td>A moment in the Workbench process at which a sync runs. Defined by this proposal.</td></tr></tbody></table><p>The ontology review is COHERENT. Beads already defines replicas, remotes, and sync. This proposal adds only the process concept of a sync point. A claim is atomic within one replica. Across replicas, how soon others see a claim is bounded by the sync points.</p><p>Other constraints:</p><ul><li><strong>Owner&#39;s priorities.</strong> Agent-loop speed comes first, and Workbench adds no per-turn work. GitHub branch noise from syncing is not acceptable.</li><li><strong><a href="./../VISION">Vision</a>.</strong> Enforce mechanically, and make ceremony earn its cost. Beads holds the work graph; Workbench does not compete with it.</li><li><strong>Error handling.</strong> A failed sync is reported, never hidden.</li></ul><h3 id="quality-bar" tabindex="-1">Quality bar <a class="header-anchor" href="#quality-bar" aria-label="Permalink to “Quality bar”">​</a></h3><ul><li>After a session&#39;s <code>mise run status</code>, the agent sees every Beads change any machine had pushed at its own latest sync point.</li><li>No turn pays for a check, a formatter run, or a prime injection it did not ask for.</li><li>No sync creates or updates anything under <code>refs/heads/</code>.</li><li>Concurrent syncs from two machines never silently lose a write that Beads does not settle by design. Push races retry, and unsafe conflicts halt and are reported.</li></ul><h3 id="remaining-uncertainty" tabindex="-1">Remaining uncertainty <a class="header-anchor" href="#remaining-uncertainty" aria-label="Permalink to “Remaining uncertainty”">​</a></h3><ul><li><strong>Claims are not atomic across machines.</strong> Two machines can claim the same item between syncs. The pull settles issue fields last-write-wins, so one claim replaces the other; the losing machine learns at its next sync. Syncing immediately after claiming narrows that window but does not close it.</li><li><strong>Network speed.</strong> Sync latency on slower networks or larger databases is unmeasured. The only measurement is a 1.28 s pull from this machine.</li><li><strong>New machines.</strong> A machine without a Dolt commit identity may fail its first merge. Beads documents this as a known failure when setting up a new machine.</li></ul><h2 id="existing-baseline" tabindex="-1">Existing baseline <a class="header-anchor" href="#existing-baseline" aria-label="Permalink to “Existing baseline”">​</a></h2><p>The relevant current behavior:</p><ul><li><strong>The extensions.</strong> <code>.omp/extensions/prime-beads.ts</code>, <code>format-after-edit.ts</code>, and <code>check-before-stop.ts</code>, plus <code>tools/format-after-edit.test.ts</code>.</li><li><strong>Where they are documented:</strong><ul><li><code>AGENTS.md</code>, in its harness setup table;</li><li><code>guides/adapting-your-harness.md</code>, in its OMP table and its &quot;Wire lifecycle events&quot; section;</li><li><code>guides/getting-started.md</code> and <code>README.md</code>;</li><li><code>.agents/rules/enforcement-hierarchy.md</code>, whose Tier 0 includes &quot;harness lifecycle wiring in <code>.omp/extensions/</code>&quot;.</li></ul></li><li><strong>The <code>tracking-work</code> skill</strong> opens with <code>bd prime</code>.</li><li><strong><code>mise run status</code></strong> (<code>tools/status.ts</code>) reports phase, situation, next action, and next actor. Its contract is in <a href="./../guides/record-validation">Record Validation and Workflow Status</a>. It says nothing about Beads.</li><li><strong><code>mise run setup</code></strong> runs <code>bd init --init-if-missing …</code>, <code>bd config set export.auto true</code>, and <code>hk install --mise</code>.</li><li><strong><code>hk.pkl</code></strong> runs <code>bd hooks run &lt;hook&gt;</code> in <code>pre-commit</code>, <code>prepare-commit-msg</code>, <code>pre-push</code>, <code>post-checkout</code>, and <code>post-merge</code>. Those keep the JSONL export current. They neither push nor pull Dolt history.</li><li><strong><code>.beads/config.yaml</code></strong> sets <code>sync.remote: &quot;git+https://github.com/markmals/workbench.git&quot;</code> and <code>export.auto: true</code>.</li></ul><p>Preserve:</p><ul><li>Beads as the work tracker.</li><li>hk&#39;s ownership of every git hook, including the Beads steps.</li><li>The committed JSONL export.</li><li>The verification rule and the gate in CI.</li></ul><p>The per-turn hooks and the prime injection are incidental.</p><h2 id="proposed-solution" tabindex="-1">Proposed solution <a class="header-anchor" href="#proposed-solution" aria-label="Permalink to “Proposed solution”">​</a></h2><p>Remove the hooks. Orientation and syncing then happen at points the process already has:</p><ul><li>when an agent orients itself (<code>mise run status</code>);</li><li>when work leaves the machine (<code>git push</code>);</li><li>when work arrives (<code>git pull</code>);</li><li>after Beads writes that another machine should see, through one explicit task.</li></ul><div class="language-text" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-dark github-light" style="--shiki-dark:#e1e4e8;--shiki-light:#24292e;--shiki-dark-bg:#24292e;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>Machine B: mise run status → sync → sees A&#39;s claims and new items → claims t-42</span></span>
<span class="line"><span>           mise run beads:sync → the claim is published</span></span>
<span class="line"><span>Machine A: next mise run status, git push, or git pull → sync → sees t-42 claimed</span></span>
<span class="line"><span>GitHub:    refs/dolt/data advances; no branch is created or updated; no banner</span></span></code></pre></div><h2 id="detailed-design" tabindex="-1">Detailed design <a class="header-anchor" href="#detailed-design" aria-label="Permalink to “Detailed design”">​</a></h2><h3 id="_1-remove-the-harness-hooks" tabindex="-1">1. Remove the harness hooks <a class="header-anchor" href="#_1-remove-the-harness-hooks" aria-label="Permalink to “1. Remove the harness hooks”">​</a></h3><p>Delete <code>.omp/extensions/prime-beads.ts</code>, <code>format-after-edit.ts</code>, and <code>check-before-stop.ts</code>, and <code>tools/format-after-edit.test.ts</code>. Workbench then wires no harness lifecycle event. <code>.omp/</code> keeps only the <code>workflow</code> tool, which <a href="https://github.com/markmals/workbench/pull/10" target="_blank" rel="noreferrer">proposal 0006</a> removes separately.</p><table tabindex="0"><thead><tr><th>Removed hook</th><th>Covered by</th></tr></thead><tbody><tr><td><code>bd prime</code> before the first turn</td><td><code>mise run status</code>, already the contract&#39;s first instruction, now reports Beads (<a href="#_2-beads-in-mise-run-status">section 2</a>).</td></tr><tr><td>Format after every edit</td><td>hk&#39;s <code>pre-commit</code> hook, which already formats staged files and stages the result. Agents may run <code>mise run fmt -- &lt;files&gt;</code>.</td></tr><tr><td>Full check before every stop</td><td>The verification rule (run <code>mise run check</code> this turn before claiming work is done), hk&#39;s <code>pre-push</code> hook (see <a href="#open-questions">Open questions</a>), and CI.</td></tr></tbody></table><h3 id="_2-beads-in-mise-run-status" tabindex="-1">2. Beads in <code>mise run status</code> <a class="header-anchor" href="#_2-beads-in-mise-run-status" aria-label="Permalink to “2. Beads in mise run status”">​</a></h3><ul><li><p><strong>Order.</strong> <code>mise run status</code> runs one sync (<a href="#_3-syncing-beads-across-machines">section 3</a>) before reporting. After the phase report, it adds a Beads section:</p><ul><li>the sync outcome;</li><li>ready work, from <code>bd ready</code>;</li><li>the project&#39;s memories, from <code>bd prime --memories-only</code>.</li></ul></li><li><p><strong>Sync outcomes:</strong></p><table tabindex="0"><thead><tr><th>Outcome</th><th>Reported as</th></tr></thead><tbody><tr><td><code>synced</code></td><td>One line.</td></tr><tr><td><code>failed</code></td><td>The reason (unreachable remote, timeout, authentication), and that the rest shows this machine&#39;s state.</td></tr><tr><td><code>conflict</code></td><td><code>bd sync</code> exit 2: the conflict needs a person to resolve it, with a link to the adoption guidance.</td></tr><tr><td><code>blocked</code></td><td><code>bd sync</code> exit 4: a dirty working set blocks publishing.</td></tr><tr><td><code>unavailable</code></td><td><code>bd</code> is missing or the workspace is not initialized, with a pointer to <code>mise run setup</code>. Shown instead of the whole section.</td></tr></tbody></table><p>The sync is limited to 20 seconds; past that its outcome is <code>failed</code>.</p></li><li><p><strong>Exit status.</strong> Beads outcomes never change the exit status of <code>mise run status</code>.</p></li><li><p><strong>JSON.</strong> <code>mise run status -- --json</code> adds a <code>beads</code> object that holds either:</p><ul><li><code>sync</code> (<code>outcome</code> and <code>detail</code>), <code>ready</code> (a list of <code>id</code>, <code>title</code>, <code>priority</code>), and <code>memories</code> (text); or</li><li><code>unavailable</code> (the reason).</li></ul></li><li><p><strong>Contract and skill updates.</strong> <a href="./../guides/record-validation">Record Validation and Workflow Status</a> gains this section as part of <code>status</code>&#39;s contract. The <code>tracking-work</code> skill&#39;s start sequence becomes <code>mise run status</code>, then <code>bd show &lt;id&gt;</code>.</p></li></ul><h3 id="_3-syncing-beads-across-machines" tabindex="-1">3. Syncing Beads across machines <a class="header-anchor" href="#_3-syncing-beads-across-machines" aria-label="Permalink to “3. Syncing Beads across machines”">​</a></h3><ul><li><p><strong>The remote</strong> is the project&#39;s own GitHub repository, through <code>sync.remote</code>, with Beads history in <code>refs/dolt/data</code>. That is unchanged from today.</p></li><li><p><strong>Every sync runs through mise.</strong> A project&#39;s <code>mise.toml</code> sets:</p><div class="language-toml" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-dark github-light" style="--shiki-dark:#e1e4e8;--shiki-light:#24292e;--shiki-dark-bg:#24292e;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-dark:#E1E4E8;--shiki-light:#24292E;">[</span><span style="--shiki-dark:#B392F0;--shiki-light:#6F42C1;">env</span><span style="--shiki-dark:#E1E4E8;--shiki-light:#24292E;">]</span></span>
<span class="line"><span style="--shiki-dark:#E1E4E8;--shiki-light:#24292E;">DOLT_REMOTE_INFO_BRANCH = </span><span style="--shiki-dark:#9ECBFF;--shiki-light:#032F62;">&quot;&quot;</span></span></code></pre></div><p>It defines a <code>beads:sync</code> task that runs <code>bd sync</code>. <code>mise run status</code>, the <code>beads:sync</code> task, and hk&#39;s mise-run steps all see that variable, so no sync publishes <code>__dolt_remote_info__</code>.</p></li><li><p><strong>Sync points:</strong></p><ol><li><code>mise run status</code> (<a href="#_2-beads-in-mise-run-status">section 2</a>).</li><li>hk&#39;s <code>pre-push</code> hook runs <code>mise run beads:sync</code> before its other steps.</li><li>hk&#39;s <code>post-merge</code> hook runs <code>mise run beads:sync</code> after a pull or merge.</li><li>After claiming, closing, or creating a Beads item another machine should see, the agent runs <code>mise run beads:sync</code>. The contract states this rule.</li></ol></li><li><p><strong>Failures in hooks.</strong> A Beads sync failure in a git hook prints its outcome and never blocks the git operation.</p></li><li><p><strong>Never:</strong></p><ul><li><code>dolt.auto-push</code>, which <code>mise run setup</code> sets to <code>false</code>;</li><li><code>bd dolt push</code>, <code>bd dolt pull</code>, or <code>bd sync</code> run outside mise;</li><li><code>git push --mirror</code> against the project&#39;s repository.</li></ul><p>The contract states the last two.</p></li><li><p><strong>Setting up a machine.</strong> <code>mise run setup</code> runs <code>bd bootstrap --yes</code> in a project that already has <code>.beads/config.yaml</code>. That restores the replica from <code>refs/dolt/data</code> instead of creating a fresh database with an unrelated history. It runs <code>bd init</code> only in a project that has no Beads workspace yet.</p></li><li><p><strong>Existing info branches.</strong> A project whose repository has <code>__dolt_remote_info__</code> deletes it once; <a href="https://github.com/gastownhall/beads/issues/5266" target="_blank" rel="noreferrer">beads#5266</a> confirms that is safe. Workbench&#39;s repository has none. When Beads publishes beads#7945, the <code>[env]</code> entry becomes redundant and harmless.</p></li></ul><h3 id="_4-documents-and-configuration-that-change" tabindex="-1">4. Documents and configuration that change <a class="header-anchor" href="#_4-documents-and-configuration-that-change" aria-label="Permalink to “4. Documents and configuration that change”">​</a></h3><ul><li><strong><code>AGENTS.md</code>:</strong><ul><li>The harness setup table drops the lifecycle rows.</li><li>Work tracking states the sync rules from <a href="#_3-syncing-beads-across-machines">section 3</a>.</li><li>The quality-gates list adds <code>mise run beads:sync</code>.</li></ul></li><li><strong><code>PROCESS.md</code>&#39;s Work Tracking section</strong> describes replicas, the remote, and the sync points.</li><li><strong><code>guides/adapting-your-harness.md</code></strong> drops &quot;Wire lifecycle events&quot; and the extension rows. A harness needs only the contract and the skills.</li><li><strong><code>guides/getting-started.md</code> and <code>README.md</code></strong> stop describing lifecycle extensions.</li><li><strong><code>.agents/rules/enforcement-hierarchy.md</code>&#39;s Tier 0</strong> drops <code>.omp/extensions/</code> and names the hk steps.</li><li><strong><a href="./../guides/record-validation">Record Validation and Workflow Status</a></strong> and the <strong><code>tracking-work</code> skill</strong> change as described in <a href="#_2-beads-in-mise-run-status">section 2</a>.</li><li><strong>Configuration:</strong><ul><li><code>mise.toml</code> gains the <code>[env]</code> entry, the <code>beads:sync</code> task, and the setup changes.</li><li><code>hk.pkl</code> gains the <code>pre-push</code> and <code>post-merge</code> steps.</li><li><code>tools/status.ts</code> and its tests gain the Beads section.</li></ul></li></ul><h2 id="compatibility" tabindex="-1">Compatibility <a class="header-anchor" href="#compatibility" aria-label="Permalink to “Compatibility”">​</a></h2><ul><li><strong>Sessions lose their automatic work.</strong> They no longer format after each edit, run the check before stopping, or receive <code>bd prime</code>. Agents run <code>mise run status</code> and the check themselves, as the existing rules already require.</li><li><strong>Beads behavior changes:</strong><ul><li>Workbench&#39;s own setup changes from <code>bd init --init-if-missing</code> to <code>bd bootstrap</code> for an existing workspace. A machine whose replica already exists keeps it.</li><li>A project that sets <code>dolt.auto-push: true</code>, such as Recon, switches to the sync points.</li><li>A project whose repository lacks <code>refs/dolt/data</code>, such as Bento, publishes it at its first sync.</li></ul></li><li><strong>Consumer projects.</strong> Until <a href="https://github.com/markmals/workbench/pull/10" target="_blank" rel="noreferrer">proposal 0006</a> delivers Workbench as a package, each consumer takes this change by copying it, like any other Workbench change today.</li></ul><h2 id="implications-on-adoption" tabindex="-1">Implications on adoption <a class="header-anchor" href="#implications-on-adoption" aria-label="Permalink to “Implications on adoption”">​</a></h2><ul><li><strong>Requirements:</strong><ul><li>bd 1.3.2 or newer, for <code>bd sync</code> and <code>bd bootstrap</code>;</li><li>Git credentials for the project&#39;s GitHub repository on every machine (pushing already needs them);</li><li>a Dolt commit identity on every machine.</li></ul></li><li><strong>Steps for an existing project:</strong><ol><li>Delete the three extensions.</li><li>Add the <code>[env]</code> entry, the <code>beads:sync</code> task, and the hk steps.</li><li>Turn off <code>dolt.auto-push</code>.</li><li>Delete any <code>__dolt_remote_info__</code> branch.</li><li>Run <code>mise run setup</code> on each machine.</li></ol></li><li><strong>Reversal.</strong> Restore the files from Git history and re-enable whatever sync the project used before.</li></ul><h2 id="scope" tabindex="-1">Scope <a class="header-anchor" href="#scope" aria-label="Permalink to “Scope”">​</a></h2><ul><li>Delete the three extensions and their test, and update the documents in <a href="#_4-documents-and-configuration-that-change">section 4</a>.</li><li>Add the Beads section to <code>mise run status</code>, with tests that stub <code>bd</code> for each outcome in <a href="#_2-beads-in-mise-run-status">section 2</a>.</li><li>Add the <code>[env]</code> entry, the <code>beads:sync</code> task, the setup change, and the hk steps to Workbench.</li></ul><h3 id="out-of-scope" tabindex="-1">Out of scope <a class="header-anchor" href="#out-of-scope" aria-label="Permalink to “Out of scope”">​</a></h3><ul><li><strong>Packaging Workbench and porting <code>status</code> to Rust.</strong> That is <a href="https://github.com/markmals/workbench/pull/10" target="_blank" rel="noreferrer">proposal 0006</a>, which ports this behavior unchanged.</li><li><strong>Migrating consumer projects,</strong> including deleting Recon&#39;s info branch. Each is a change in that repository.</li><li><strong>Changing Beads itself</strong>, such as beads#7945.</li><li><strong>A shared Dolt server, a DoltHub or bucket remote, or per-machine identities for claims.</strong> See Alternatives and Future directions.</li></ul><h2 id="preview" tabindex="-1">Preview <a class="header-anchor" href="#preview" aria-label="Permalink to “Preview”">​</a></h2><ul><li><strong>Repository shape:</strong> process tooling with CLI checks.</li><li><strong>Artifact:</strong> this branch, exercised against the real GitHub remote from two clones, each with its own replica. Two clones on one machine behave as two machines for Beads; a second physical machine is optional.</li><li><strong>Exercise:</strong><ol><li>In clone A, run <code>mise run status</code> and read the Beads section.</li><li>In clone B, claim an item and run <code>mise run beads:sync</code>.</li><li>In A, run <code>mise run status</code> and see the claim.</li><li>Push a branch from A and confirm hk synced.</li><li>Run <code>git ls-remote origin</code> and confirm there is no <code>refs/heads/__dolt_remote_info__</code>.</li><li>Run <code>mise run status</code> with the network off and see the <code>failed</code> outcome.</li></ol></li><li><strong>Cleanup:</strong> close the probe items, sync, and delete the second clone.</li></ul><h2 id="policies-and-decisions-checked" tabindex="-1">Policies and decisions checked <a class="header-anchor" href="#policies-and-decisions-checked" aria-label="Permalink to “Policies and decisions checked”">​</a></h2><ul><li><strong>Policies and decisions.</strong> None: <code>policies/</code> and <code>decisions/</code> hold only their READMEs.</li><li><strong><a href="./../VISION">VISION.md</a>.</strong> &quot;Ceremony must earn its cost&quot;: the hooks are removed on measured cost. &quot;Enforce mechanically&quot;: checks remain at commit, push, and CI. &quot;Not an issue tracker&quot;: Beads keeps the work graph.</li><li><strong><a href="./0003-fit-the-harness-to-current-models">Proposal 0003</a></strong> recorded <code>check-before-stop</code>&#39;s timeout in Trove and suggested a fast-subset stop hook. This proposal removes the hook instead; see Alternatives.</li><li><strong><a href="./0005-current-specifications">Proposal 0005</a></strong> put <code>status</code>&#39;s contract in <code>guides/record-validation.md</code>, which this proposal extends.</li><li><strong><a href="https://github.com/markmals/workbench/pull/10" target="_blank" rel="noreferrer">Proposal 0006</a></strong> depends on this one: its package declares no harness hooks, and its Rust <code>status</code> ports this Beads section.</li><li><strong><code>.agents/rules/enforcement-hierarchy.md</code>.</strong> Tier 0 loses the harness wiring and gains the hk Beads steps. Every remaining check runs whether or not the agent remembers.</li></ul><h2 id="future-directions" tabindex="-1">Future directions <a class="header-anchor" href="#future-directions" aria-label="Permalink to “Future directions”">​</a></h2><ul><li><strong>Visible claimants.</strong> A per-machine Beads actor, such as <code>BEADS_ACTOR=&lt;user&gt;@&lt;host&gt;</code>, would show which machine holds a claim. All machines currently claim as the same Git user.</li><li><strong>A shared server.</strong> A single Dolt server, for example on a home server over Tailscale, would make claims atomic across machines if double claims become a real problem.</li><li><strong>Timed syncs.</strong> A sync on a timer could serve long sessions that rarely orient, push, or pull.</li></ul><h2 id="alternatives-considered" tabindex="-1">Alternatives considered <a class="header-anchor" href="#alternatives-considered" aria-label="Permalink to “Alternatives considered”">​</a></h2><ul><li><strong>Cheaper hooks.</strong> A fast subset of the check before stopping, or a check that the gate passed since the last edit, still forces work before any pause that follows an edit, including mid-work questions. Formatting at commit time already exists.</li><li><strong>A DoltHub remote.</strong> Hosted Dolt remotes are built for many writers and offer a web view of the database. They add an account, credentials on every machine, and a service outside GitHub. Suppressing the info branch removes the banner without them.</li><li><strong>An S3 or GCS bucket.</strong> No server to run, but it needs a cloud account and credentials on every machine.</li><li><strong>A shared Dolt server</strong> (Beads server mode, reached over Tailscale). One database means atomic claims and no merges. But every machine must reach the server to use Beads at all, and it adds a service to run and back up.</li><li><strong>A dedicated repository for Beads data.</strong> It moves the banner to a repository nobody watches, at the cost of one more repository per project.</li><li><strong><code>dolt.auto-push</code>.</strong> It does network work on every write, and Beads documents it as unsafe for racing writers. Pushes from shells without the variable would also publish the info branch.</li><li><strong>JSONL in Git.</strong> Beads documents the export as unsuitable for sync: import is upsert-only and loses deletions.</li></ul><h2 id="open-questions" tabindex="-1">Open questions <a class="header-anchor" href="#open-questions" aria-label="Permalink to “Open questions”">​</a></h2><ul><li>[NEEDS CLARIFICATION: Should hk&#39;s <code>pre-push</code> hook keep running the full <code>mise run check</code>, or should the gate run only in CI, with the agent waiting for CI (<code>gh pr checks --watch</code>) before marking a pull request ready? Dropping it removes a 4–8 minute wait from every push in Trove-sized projects, at the cost of failing commits reaching a draft pull request before CI flags them.]</li></ul>`,68)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};